PREFIX brick: <http://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick#>
SELECT DISTINCT ?zone ?tp ?set ?tpUri ?setUri ?tsidTP ?tsidSet WHERE {
  ?zone brick:hasSubclass* ?z .
  ?z rdf:type brick:Location .
} LIMIT 5

SELECT DISTINCT ?name WHERE {
  ?name rdfs:label ?l . FILTER(str(?l)="Perimeter_top_ZN_2")
} LIMIT 5

SELECT DISTINCT ?name ?lab WHERE {
  ?name rdfs:label ?l . FILTER(CONTAINS(?l,"Z03") || CONTAINS(?l,"ZN_2") || CONTAINS(?l,"Perimeter"))
  BIND(str(?name) AS ?name)
  BIND(?l AS ?lab)
} LIMIT 50

PREFIX brick: <http://brickschema.org/schema/Brick#>
SELECT DISTINCT ?p ?cls ?tsid WHERE {
  ?p brick:hasLocation <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F3_Z03> .
  ?p rdf:type ?cls .
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
}

PREFIX brick: <http://brickschema.org/schema/Brick#>
SELECT DISTINCT ?p ?cls ?tsid WHERE {
  ?p brick:hasLocation <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F3_Z03> .
  ?p rdf:type ?cls .
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?p ref:hasExternalReference ?ext }
}

SELECT DISTINCT ?p ?cls ?tsid WHERE {
  ?p brick:hasLocation ?loc .
  ?loc rdfs:label ?lab .
  FILTER(str(?lab)="Perimeter_top_ZN_2")
  ?p rdf:type ?cls .
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
}

SELECT DISTINCT ?pt ?cls ?tsid ?ext WHERE {
  <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F3_Z03> <https://brickschema.org/schema/Brick#hasPoint> ?pt .
  ?pt rdf:type ?cls .
  OPTIONAL { ?pt <https://brickschema.org/schema/Brick/ref#hasTimeseriesId> ?tsid }
  OPTIONAL { ?pt <https://brickschema.org/schema/Brick/ref#hasExternalReference> ?ext }
}

